spec.query:
from(bucket: "smartline_kpis")
  |> range(start: -1m)
  |> filter(fn: (r) => r["_measurement"] == "OEE")
  |> last()
  |> map(fn: (r) => ({
      _value: float(v: uint(v: now()) - uint(v: r._time)) / 1000000.0, _measurement: "Stream Lag (ms)"
  }))
  |> keep(columns: ["_value", "_measurement"])
